    "taxonId": 170408,
    "summary": "Flowering shrub or small tree native to southern and central China, Taiwan and South Korea. Numerous short spines line its stems and leaf stalks, while rough reddish-brown berry shells split to reveal black seeds; it is one source of Sichuan pepper.",
    "humanEdibility": "yes",
    "edibilityNote": "This species is one of several used to produce Sichuan pepper.",
    "evidence": {
      "summary": ["s1:p1", "s1:p2"],
      "humanEdibility": ["s1:p1"]
    }
  },
