    "taxonId": 84280,
    "summary": "Annual flowering herb native to Great Britain, Iceland, central Europe and Western Asia. It blooms in July and August and is a known host of flax rust.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p2"],
      "humanEdibility": []
    }
  },
